// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.utilimport timber.log.Timberimport android.app.Activityimport android.app.Applicationimport android.content.ComponentNameimport android.os.Bundleimport java.util.concurrent.atomic.AtomicReferenceimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Foreground Activity Tracker (Module 10 v2 — audit defect C fix). * * Maintains the current foreground [Activity] reference for handlers that * need window-level access: *  - [com.roshan.persona.system.handler.BrightnessHandler] — applies window *    brightness via `WindowManager.LayoutParams.screenBrightness`. *  - [com.roshan.persona.system.handler.ScreenHandler] — toggles *    `FLAG_KEEP_SCREEN_ON` on the current activity's window. * * ## Wiring * * The tracker is `@Singleton @Inject`-constructed. The `:app` module's * `Application.onCreate` registers an [Application.ActivityLifecycleCallbacks] * that delegates to [onActivityResumed] / [onActivityPaused] so this tracker * always knows the foreground activity. * * Handlers access the current activity via [currentActivity] (a plain * property — returns null when NOUS is in the background). * * ## Why not `ActivityManager.getRunningTasks`? * * `getRunningTasks(1)` was deprecated in API 21 and returns only the caller's * own tasks on API 5+. The lifecycle-callbacks approach is the standard * pattern (used by Firebase, Glide, all lifecycle-aware libraries) — it's * accurate, doesn't require permissions, and is real Android API (no * reflection, no hidden APIs). * * ## Thread safety * * The current activity is held in an [AtomicReference] — safe to read from * any thread (handlers may run on Dispatchers.IO). Writes happen on the main * thread (where lifecycle callbacks fire). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Display</a> */@Singletonclass ForegroundActivityTracker @Inject constructor() {    private val ref = AtomicReference<Activity?>(null)    /** The current foreground [Activity], or null if NOUS is in the background. */    val currentActivity: Activity?        get() = ref.get()    /** The current foreground activity's [ComponentName], or null. */    val currentComponentName: ComponentName?        get() = ref.get()?.let { activity ->            try {                ComponentName(activity.packageName, activity.javaClass.name)            } catch (t: Throwable) {                Timber.tag(TAG).w("Failed to build ComponentName", t)                null            }        }    /**     * Register this tracker with the [Application] via lifecycle callbacks.     *     * Called from `Application.onCreate()` in `:app`. Idempotent — safe to     * call multiple times (only the first registration takes effect).     */    fun register(application: Application) {        try {            application.registerActivityLifecycleCallbacks(                object : Application.ActivityLifecycleCallbacks {                    override fun onActivityResumed(activity: Activity) {                        ref.set(activity)                        Timber.tag(TAG).d("Foreground: ${activity.javaClass.name}")                    }                    override fun onActivityPaused(activity: Activity) {                        // Clear only if the same activity is still tracked — avoids                        // race when a new activity resumed before pause fired.                        ref.compareAndSet(activity, null)                    }                    // Unused callbacks — tracker only cares about resume/pause.                    override fun onActivityCreated(                        activity: Activity, savedInstanceState: android.os.Bundle?,                    ) = Unit                    override fun onActivityStarted(activity: Activity) = Unit                    override fun onActivityStopped(activity: Activity) = Unit                    override fun onActivitySaveInstanceState(                        activity: Activity, outState: android.os.Bundle,                    ) = Unit                    override fun onActivityDestroyed(activity: Activity) {                        ref.compareAndSet(activity, null)                    }                },            )        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to register activity lifecycle callbacks")        }    }    private companion object {        private const val TAG = "FgActivityTracker"    }}